// Writes CHANGELOG.md at the root: every release in one place, newest first, with its date and
// what changed in each package. The packages' own CHANGELOG.md files (written by changesets)
// are the source; this file is generated, so edit a changeset, not this.
//
//   node scripts/changelog.mjs              rewrite CHANGELOG.md
//   node scripts/changelog.mjs --notes 0.2.3   print one release's notes (for a GitHub Release)
//
// A release is named after the version of `mbingpdf`. An adapter's entry belongs to the
// release in which its version first appears.
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const PACKAGES = [
  ["mbingpdf", "packages/mbingpdf"],
  ["@mbingpdf/react", "packages/react"],
  ["@mbingpdf/vue", "packages/vue"],
  ["@mbingpdf/dev", "packages/dev"],
];

const git = (...args) => {
  try {
    return execFileSync("git", args, {
      cwd: root,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    return undefined;
  }
};

/** The sections of a package's changelog, by version. */
function sections(directory) {
  const text = readFileSync(join(root, directory, "CHANGELOG.md"), "utf8");
  const out = new Map();
  for (const part of text.split(/^## /m).slice(1)) {
    const [version, ...rest] = part.split("\n");
    const body = rest
      .join("\n")
      // The commit a change came from says nothing to a reader; neither does the list of
      // sibling packages that were bumped along.
      .replace(/^- [0-9a-f]{7}: /gm, "- ")
      .replace(/^- Updated dependencies[^\n]*\n(?: {2}- [^\n]*\n?)*/gm, "")
      // "Minor Changes" and "Patch Changes" repeat what the version number already says.
      .replace(/^### (Major|Minor|Patch) Changes\n+/gm, "")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
    out.set(version.trim(), body);
  }
  return out;
}

const versionAt = (ref, directory) => {
  const manifest =
    ref === undefined
      ? readFileSync(join(root, directory, "package.json"), "utf8")
      : git("show", `${ref}:${directory}/package.json`);
  return manifest ? JSON.parse(manifest).version : undefined;
};

const logs = new Map(PACKAGES.map(([name, directory]) => [name, sections(directory)]));
const releases = [...(logs.get("mbingpdf")?.keys() ?? [])]; // newest first
const today = new Date().toISOString().slice(0, 10);

function release(version, index) {
  const tag = git("rev-parse", "--verify", "--quiet", `v${version}^{commit}`)
    ? `v${version}`
    : undefined;
  const older = releases[index + 1];
  const date = tag ? git("log", "-1", "--format=%cs", tag) : today;
  const parts = [];
  for (const [name, directory] of PACKAGES) {
    const now = name === "mbingpdf" ? version : versionAt(tag, directory);
    const before =
      name === "mbingpdf" ? older : older ? versionAt(`v${older}`, directory) : undefined;
    if (now === undefined || now === before) continue;
    const body = logs.get(name)?.get(now);
    if (body) parts.push({ name, version: now, body });
  }
  return { version, date, parts };
}

function notes({ parts }) {
  return parts.map(({ name, version, body }) => `### ${name} ${version}\n\n${body}`).join("\n\n");
}

const all = releases.map(release);
const wanted = process.argv.indexOf("--notes");
if (wanted !== -1) {
  const found = all.find((entry) => entry.version === process.argv[wanted + 1]);
  if (!found) {
    console.error(`No release ${process.argv[wanted + 1]} in packages/mbingpdf/CHANGELOG.md`);
    process.exit(1);
  }
  console.log(notes(found));
} else {
  const text = [
    "# Changelog",
    "",
    "Every release of mbingpdf and its companion packages, newest first. A release is named after",
    "the version of `mbingpdf`; the adapters (`@mbingpdf/react`, `@mbingpdf/vue`) and the dev server",
    "(`@mbingpdf/dev`) are listed under the release they came out with. How versions are numbered",
    "is in [docs/09-versioning.md](docs/09-versioning.md).",
    "",
    "This file is generated by `scripts/changelog.mjs` from the changesets; do not edit it by hand.",
    "",
    ...all.flatMap((entry) => [`## ${entry.version} — ${entry.date}`, "", notes(entry), ""]),
  ].join("\n");
  writeFileSync(join(root, "CHANGELOG.md"), `${text.trimEnd()}\n`);
  console.log(`CHANGELOG.md: ${all.length} releases`);
}
